using System;using System.Collections.Generic;using System.Diagnostics;using System.Drawing;using System.IO;using System.IO.Compression;using System.Linq;using System.Reflection;using System.Security.Cryptography;using System.Text;using System.Text.RegularExpressions;using System.Threading.Tasks;using System.Windows.Forms;using System.Xml.Serialization;
namespace DuelStructureSetup {
 public class PayloadFile {public string Path,Sha,Scope;}
 public class Payload {public string Version,MetadataSha,UnitySha,GameAssemblySha,Runtime,MonoAssemblySha,UnityVersion;public List<PayloadFile> Files=new List<PayloadFile>();}
 public class InstalledFile {public string Path,Sha,Scope,OriginalSha,Backup;public bool Existed;}
 public class Receipt {public string Product="cn.duelstructure.mdpro3";public string Version;public bool Installed;public List<InstalledFile> Files=new List<InstalledFile>();}
 public class Engine {
  public const string State="BepInEx/DuelStructureInstaller/install.xml";
  readonly Payload primary,mono;Payload selected;public Payload Payload{get{return selected??primary;}}
  public Engine(){using(var s=Assembly.GetExecutingAssembly().GetManifestResourceStream("duelstructure.manifest.xml"))primary=(Payload)new XmlSerializer(typeof(Payload)).Deserialize(s);using(var s=Assembly.GetExecutingAssembly().GetManifestResourceStream("duelstructure.mono.manifest.xml"))if(s!=null)mono=(Payload)new XmlSerializer(typeof(Payload)).Deserialize(s);}
  public static string Hash(string path){using(var s=File.OpenRead(path))using(var h=SHA256.Create())return BitConverter.ToString(h.ComputeHash(s)).Replace("-","").ToLowerInvariant();}
  public static string Safe(string root,string relative){if(string.IsNullOrEmpty(relative)||relative.Contains(":")||Path.IsPathRooted(relative))throw new IOException("安装文件路径无效");var full=Path.GetFullPath(Path.Combine(root,relative.Replace('/',Path.DirectorySeparatorChar)));var prefix=Path.GetFullPath(root).TrimEnd(Path.DirectorySeparatorChar)+Path.DirectorySeparatorChar;if(!full.StartsWith(prefix,StringComparison.OrdinalIgnoreCase))throw new IOException("安装文件超出目标目录");return full;}
  static void NoLinks(string root,string path){for(var p=path;!string.Equals(p,root,StringComparison.OrdinalIgnoreCase)&&p!=null;p=Path.GetDirectoryName(p)){if((Directory.Exists(p)||File.Exists(p))&&(File.GetAttributes(p)&FileAttributes.ReparsePoint)!=0)throw new IOException("安装目标内存在重定向目录，请选择普通的本体目录："+p);}}
  public static string Backend(string root){if(string.IsNullOrWhiteSpace(root)||!File.Exists(Path.Combine(root,"MDPro3.exe")))return "Unknown";if(File.Exists(Path.Combine(root,"GameAssembly.dll"))&&File.Exists(Path.Combine(root,"MDPro3_Data/il2cpp_data/Metadata/global-metadata.dat")))return "IL2CPP";if(File.Exists(Path.Combine(root,"MDPro3_Data/Managed/Assembly-CSharp.dll")))return "Mono";return "Unknown";}
  public string Validate(string root,bool compatibility){
   if(string.IsNullOrWhiteSpace(root))throw new IOException("请选择 MDPro3 本体文件夹");root=Path.GetFullPath(root).TrimEnd(Path.DirectorySeparatorChar);
   if(!File.Exists(Path.Combine(root,"MDPro3.exe")))throw new IOException("所选目录没有 MDPro3.exe，请选择本体文件夹。");
   if(Backend(root)=="Mono"){if(mono==null)throw new IOException("当前安装器未包含 Mono 组件，请使用支持双运行版本的新版安装器。");selected=mono;var managed=Path.Combine(root,"MDPro3_Data/Managed/Assembly-CSharp.dll");var unity=Path.Combine(root,"UnityPlayer.dll");if(!File.Exists(unity))throw new IOException("Mono 本体缺少 UnityPlayer.dll。");if(compatibility&&(Hash(managed)!=mono.MonoAssemblySha||FileVersionInfo.GetVersionInfo(unity).FileVersion!=mono.UnityVersion))throw new IOException("已识别 Mono 本体，但程序版本尚未适配。请导出适配资料以核对版本。");return root;}selected=primary;
   if(!File.Exists(Path.Combine(root,"UnityPlayer.dll")))throw new IOException("这个本体缺少 UnityPlayer.dll，请先检查本体是否完整。");
   if(!File.Exists(Path.Combine(root,"GameAssembly.dll")))throw new IOException("这个本体尚未识别为受支持的运行版本，缺少 GameAssembly.dll。可点击“导出适配资料”提供目录信息。");
   var meta=Path.Combine(root,"MDPro3_Data/il2cpp_data/Metadata/global-metadata.dat");if(!File.Exists(meta))throw new IOException("已找到 IL2CPP 程序，但缺少 global-metadata.dat，请检查本体是否完整。");
   if(compatibility&&(Hash(meta)!=Payload.MetadataSha||Hash(Path.Combine(root,"UnityPlayer.dll"))!=Payload.UnitySha||Hash(Path.Combine(root,"GameAssembly.dll"))!=Payload.GameAssemblySha))throw new IOException("已识别到 IL2CPP 本体，但与适配版本不同。当前支持 MDPro3 v1.4.8 / Unity 6000.0.24f1 / Windows x64。可点击“导出适配资料”提供版本信息。");return root;
  }
  public string Describe(string root){if(string.IsNullOrWhiteSpace(root)||!File.Exists(Path.Combine(root,"MDPro3.exe")))throw new IOException("请选择包含 MDPro3.exe 的本体文件夹。");var text=new StringBuilder();text.AppendLine("决构编辑器：本体适配资料");text.AppendLine("Runtime: "+Backend(root));foreach(string name in new[]{"MDPro3.exe","UnityPlayer.dll","GameAssembly.dll","MDPro3_Data/il2cpp_data/Metadata/global-metadata.dat"}){string file=Path.Combine(root,name);if(!File.Exists(file)){text.AppendLine(name+": missing");continue;}text.AppendLine(name+": "+new FileInfo(file).Length+" bytes / SHA256 "+Hash(file));if(name.EndsWith(".exe")||name.EndsWith(".dll")){var info=FileVersionInfo.GetVersionInfo(file);text.AppendLine("Version: "+info.FileVersion+" / "+info.ProductVersion);}}string managed=Path.Combine(root,"MDPro3_Data/Managed");if(Directory.Exists(managed)){text.AppendLine("Managed assemblies:");foreach(string file in Directory.GetFiles(managed,"*.dll").OrderBy(f=>f)){if((File.GetAttributes(file)&FileAttributes.ReparsePoint)!=0)continue;text.AppendLine(Path.GetFileName(file)+" / "+new FileInfo(file).Length+" bytes / SHA256 "+Hash(file));}}return text.ToString();}
  public void ExportInfo(string root,string output,Action<int,string> progress){string description=Describe(root);if(!output.EndsWith(".zip",StringComparison.OrdinalIgnoreCase))throw new IOException("适配资料应保存为 ZIP 文件。");if(File.Exists(output))throw new IOException("该资料文件已经存在，请使用其他名称。");string temp=output+".writing-"+Guid.NewGuid().ToString("N");try{using(var stream=File.Create(temp))using(var zip=new ZipArchive(stream,ZipArchiveMode.Create)){var entry=zip.CreateEntry("版本信息.txt");using(var writer=new StreamWriter(entry.Open(),new UTF8Encoding(false)))writer.Write(description);string loaderLog=Path.Combine(root,"BepInEx/LogOutput.log");if(File.Exists(loaderLog)&&new FileInfo(loaderLog).Length<16*1024*1024){using(var read=new StreamReader(new FileStream(loaderLog,FileMode.Open,FileAccess.Read,FileShare.ReadWrite))){var lines=new StringBuilder();string line;int follow=0;while((line=read.ReadLine())!=null){bool own=line.Contains("BepInEx")||line.Contains("决构编辑器")||line.Contains("DuelStructure")||line.Contains("Preloader")||line.Contains("Chainloader");if(own||follow>0){lines.AppendLine(line);follow=own&&line.Contains("Error")?12:Math.Max(0,follow-1);}}var logEntry=zip.CreateEntry("加载器与编辑器启动信息.txt");using(var logWriter=new StreamWriter(logEntry.Open(),new UTF8Encoding(false)))logWriter.Write(lines.ToString());}}string managed=Path.Combine(root,"MDPro3_Data/Managed");var files=Directory.Exists(managed)?Directory.GetFiles(managed,"*.dll").Where(f=>(File.GetAttributes(f)&FileAttributes.ReparsePoint)==0).OrderBy(f=>f).ToArray():new string[0];int index=0;foreach(string file in files){var item=zip.CreateEntry("MDPro3_Data/Managed/"+Path.GetFileName(file),CompressionLevel.Optimal);using(var source=File.OpenRead(file))using(var dest=item.Open())source.CopyTo(dest);Progress(progress,++index*95/Math.Max(1,files.Length),"整理程序组件 "+index+" / "+files.Length);}}File.Move(temp,output);Progress(progress,100,"适配资料已导出，可将 ZIP 发给开发者。");}finally{if(File.Exists(temp))File.Delete(temp);}}

  static void CheckStopped(string root){foreach(var p in Process.GetProcessesByName("MDPro3")){try{if(string.Equals(Path.GetFullPath(p.MainModule.FileName),Path.Combine(root,"MDPro3.exe"),StringComparison.OrdinalIgnoreCase))throw new IOException("请先退出这个目录中的 MDPro3，再安装或卸载。");}catch(System.ComponentModel.Win32Exception){throw new IOException("请先关闭正在运行的 MDPro3。");}finally{p.Dispose();}}}
  Receipt Read(string root){var path=Safe(root,State);if(!File.Exists(path))return new Receipt();using(var s=File.OpenRead(path)){var r=(Receipt)new XmlSerializer(typeof(Receipt)).Deserialize(s);if(r.Product!="cn.duelstructure.mdpro3")throw new IOException("安装记录无法识别");foreach(var f in r.Files){Safe(root,f.Path);if(f.Backup!=null){Safe(root,f.Backup);if(!f.Backup.StartsWith("BepInEx/DuelStructureInstaller/originals/",StringComparison.Ordinal))throw new IOException("原始文件备份记录无效");}}return r;}}
  static void Atomic(string path,byte[] bytes){Directory.CreateDirectory(Path.GetDirectoryName(path));string temp=path+".installing-"+Guid.NewGuid().ToString("N");try{File.WriteAllBytes(temp,bytes);if(File.Exists(path))File.Replace(temp,path,null);else File.Move(temp,path);}finally{if(File.Exists(temp))File.Delete(temp);}}
  static byte[] Xml(Receipt receipt){using(var s=new MemoryStream()){new XmlSerializer(typeof(Receipt)).Serialize(s,receipt);return s.ToArray();}}
  static byte[] ConsoleOff(byte[] original){string text=Encoding.UTF8.GetString(original);var section=new Regex(@"(?ms)(^\[Logging\.Console\][^\S\r\n]*\r?\n)(.*?)(?=^\[|\z)");if(section.IsMatch(text))text=section.Replace(text,m=>m.Groups[1].Value+(Regex.IsMatch(m.Groups[2].Value,@"(?m)^Enabled\s*=")?Regex.Replace(m.Groups[2].Value,@"(?m)^Enabled\s*=.*$","Enabled = false"):m.Groups[2].Value+"\r\nEnabled = false\r\n"));else text+="\r\n[Logging.Console]\r\nEnabled = false\r\n";return new UTF8Encoding(false).GetBytes(text);}
  void LoaderCheck(string root){foreach(string rel in new[]{"winhttp.dll",(Payload.Runtime=="Mono"?"BepInEx/core/BepInEx.dll":"BepInEx/core/BepInEx.Unity.IL2CPP.dll")}){string file=Safe(root,rel);var expected=Payload.Files.Single(f=>f.Path==rel);if(File.Exists(file)&&Hash(file)!=expected.Sha)throw new IOException("检测到其他版本的加载器，为保留现有插件，本安装器不会覆盖："+rel+"。请选择干净的兼容本体，或使用配套扩展更新包。");}}
  static void Progress(Action<int,string> progress,int value,string text){if(progress!=null)progress(value,text);}
  public void Install(string root,Action<int,string> progress){root=Validate(root,true);CheckStopped(root);LoaderCheck(root);foreach(var f in Payload.Files)NoLinks(root,Safe(root,f.Path));NoLinks(root,Safe(root,State));var receipt=Read(root);if(Payload.Runtime=="Mono"&&File.Exists(Safe(root,"BepInEx/core/BepInEx.Unity.IL2CPP.dll"))||Payload.Runtime!="Mono"&&File.Exists(Safe(root,"BepInEx/core/BepInEx.dll")))throw new IOException("这个目录已有另一种运行版本的加载器，请选择与本体对应的干净目录。");string id=Guid.NewGuid().ToString("N");string stage=Safe(root,".duelstructure-install-"+id);Directory.CreateDirectory(stage);var changed=new List<string>();var originals=new Dictionary<string,byte[]>();
   try{using(var input=Assembly.GetExecutingAssembly().GetManifestResourceStream(Payload.Runtime=="Mono"?"duelstructure.mono.payload.zip":"duelstructure.payload.zip"))using(var zip=new ZipArchive(input,ZipArchiveMode.Read)){int index=0;foreach(var f in Payload.Files){var entry=zip.GetEntry(f.Path);if(entry==null)throw new IOException("安装包缺少："+f.Path);string dest=Safe(stage,f.Path);Directory.CreateDirectory(Path.GetDirectoryName(dest));using(var source=entry.Open())using(var target=File.Create(dest))source.CopyTo(target);if(Hash(dest)!=f.Sha)throw new IOException("安装包校验失败："+f.Path);Progress(progress,++index*45/Payload.Files.Count,"校验安装文件 "+index+" / "+Payload.Files.Count);}}
    int done=0;foreach(var f in Payload.Files){string path=Safe(root,f.Path);byte[] bytes=File.ReadAllBytes(Safe(stage,f.Path));if(Payload.Runtime=="Mono"&&f.Path=="doorstop_config.ini")bytes=new UTF8Encoding(false).GetBytes(Encoding.UTF8.GetString(bytes).Replace("@DUEL_MONO_LIBS@",Safe(root,"BepInEx/DuelStructureMonoRuntime")));if(f.Scope=="config"&&File.Exists(path))bytes=ConsoleOff(File.ReadAllBytes(path));string sha;using(var h=SHA256.Create())sha=BitConverter.ToString(h.ComputeHash(bytes)).Replace("-","").ToLowerInvariant();var saved=receipt.Files.FirstOrDefault(x=>x.Path==f.Path);if(saved==null){saved=new InstalledFile{Path=f.Path,Scope=f.Scope,Existed=File.Exists(path)};if(saved.Existed){saved.OriginalSha=Hash(path);saved.Backup="BepInEx/DuelStructureInstaller/originals/"+id+"/"+f.Path;string backup=Safe(root,saved.Backup);NoLinks(root,backup);Directory.CreateDirectory(Path.GetDirectoryName(backup));File.Copy(path,backup,false);}receipt.Files.Add(saved);}saved.Sha=sha;
     if(!File.Exists(path)||Hash(path)!=sha){originals[path]=File.Exists(path)?File.ReadAllBytes(path):null;Atomic(path,bytes);changed.Add(path);}Progress(progress,45+(++done*50/Payload.Files.Count),(f.Scope=="extension"?"安装决构编辑器":"准备运行组件")+" "+done+" / "+Payload.Files.Count);
    }receipt.Version=Payload.Version;receipt.Installed=true;Atomic(Safe(root,State),Xml(receipt));Progress(progress,100,"安装完成。启动 MDPro3，在主菜单选择“决构编辑对局”。");
   }catch{foreach(var path in changed.AsEnumerable().Reverse()){if(originals[path]==null)File.Delete(path);else Atomic(path,originals[path]);}throw;}finally{if(Directory.Exists(stage))Directory.Delete(stage,true);}
  }
  public void Uninstall(string root,Action<int,string> progress){root=Validate(root,false);CheckStopped(root);var receipt=Read(root);if(!receipt.Installed)throw new IOException("这个目录没有本安装器安装的决构编辑器。");var files=receipt.Files.Where(f=>(f.Scope=="extension"||f.Scope=="patcher")).ToArray();foreach(var f in files){if(f.Scope=="extension"&&!f.Path.StartsWith("BepInEx/plugins/DuelStructure/",StringComparison.Ordinal))throw new IOException("扩展文件记录无效");if(f.Scope=="patcher"&&!f.Path.StartsWith("BepInEx/patchers/DuelStructure/",StringComparison.Ordinal))throw new IOException("适配组件记录无效");if(f.Scope=="config"&&f.Path!="BepInEx/config/BepInEx.cfg")throw new IOException("配置文件记录无效");string path=Safe(root,f.Path);NoLinks(root,path);if((f.Scope=="extension"||f.Scope=="patcher")&&File.Exists(path)&&Hash(path)!=f.Sha)throw new IOException("扩展文件已被其他程序修改，已保留，请先备份后处理："+f.Path);if(f.Existed&&(!File.Exists(Safe(root,f.Backup))||Hash(Safe(root,f.Backup))!=f.OriginalSha))throw new IOException("原始文件备份校验失败，尚未卸载："+f.Path);}
   var changed=new Dictionary<string,byte[]>();try{int count=0;foreach(var f in files){string path=Safe(root,f.Path);if(f.Scope=="config"&&File.Exists(path)&&Hash(path)!=f.Sha)continue;changed[path]=File.Exists(path)?File.ReadAllBytes(path):null;if(f.Existed)Atomic(path,File.ReadAllBytes(Safe(root,f.Backup)));else if(File.Exists(path))File.Delete(path);Progress(progress,++count*95/Math.Max(1,files.Length),"恢复原有编辑器文件 "+count+" / "+files.Length);}receipt.Installed=false;Atomic(Safe(root,State),Xml(receipt));Progress(progress,100,"编辑器已卸载。已保留加载器、其他插件、卡组、存档和录像。");}catch{foreach(var entry in changed){if(entry.Value==null)File.Delete(entry.Key);else Atomic(entry.Key,entry.Value);}throw;}
  }
 }
 public class SetupForm:Form {
  readonly TextBox path=new TextBox(),details=new TextBox();readonly Button browse=new Button(),install=new Button(),remove=new Button(),check=new Button(),export=new Button();readonly ProgressBar bar=new ProgressBar();readonly Label status=new Label();readonly Engine engine=new Engine();bool busy;
  public SetupForm(){Text="决构编辑器 · MDPro3 安装器 0.3.1";FormBorderStyle=FormBorderStyle.FixedDialog;MaximizeBox=false;ClientSize=new Size(700,460);MinimumSize=new Size(716,499);StartPosition=FormStartPosition.CenterScreen;Font=new Font("Microsoft YaHei UI",10);BackColor=Color.FromArgb(245,247,250);var title=new Label{Text="决构编辑器",Font=new Font("Microsoft YaHei UI",22,FontStyle.Bold),AutoSize=true,Location=new Point(26,20)};Controls.Add(title);Controls.Add(new Label{Text="MDPro3 · Mono / IL2CPP · Windows 64 位",AutoSize=true,Location=new Point(29,75)});Controls.Add(new Label{Text="选择包含 MDPro3.exe 的本体文件夹",AutoSize=true,Location=new Point(29,120)});path.SetBounds(30,150,534,30);path.Text=Directory.Exists(@"D:\Game\MDPro3")?@"D:\Game\MDPro3":"";browse.Text="浏览…";browse.SetBounds(575,149,95,32);browse.Click+=(s,e)=>{using(var dialog=new FolderBrowserDialog{Description="选择 MDPro3 本体文件夹",SelectedPath=path.Text})if(dialog.ShowDialog()==DialogResult.OK)path.Text=dialog.SelectedPath;};details.SetBounds(30,198,640,106);details.Multiline=true;details.ReadOnly=true;details.BorderStyle=BorderStyle.None;details.BackColor=BackColor;details.Text="自动识别 Mono / IL2CPP，安装对应加载器与运行库。\r\n支持全新安装与更新，替换前会保留原始文件备份。\r\n不会改动本体程序、卡组、全局存档和录像。\r\n卸载仅恢复或移除编辑器，保留加载器与其他插件。";bar.SetBounds(30,316,640,19);status.SetBounds(30,344,640,40);install.Text="安装 / 更新";install.SetBounds(30,400,155,36);check.Text="检查目录";check.SetBounds(198,400,130,36);export.Text="导出适配资料";export.SetBounds(340,400,170,36);export.Click+=async(s,e)=>await Export();remove.Text="卸载编辑器";remove.SetBounds(525,400,145,36);Controls.AddRange(new Control[]{path,browse,details,bar,status,install,check,export,remove});install.Click+=async(s,e)=>await Run(false);remove.Click+=async(s,e)=>{if(MessageBox.Show(this,"卸载将恢复安装前的扩展文件，并保留加载器、存档和录像。是否继续？","卸载编辑器",MessageBoxButtons.YesNo,MessageBoxIcon.Question)==DialogResult.Yes)await Run(true);};check.Click+=(s,e)=>{try{engine.Validate(path.Text,true);status.Text="目录与适配版本检查通过。请退出游戏后安装。";}catch(Exception ex){MessageBox.Show(this,ex.Message,"目录检查",MessageBoxButtons.OK,MessageBoxIcon.Information);}};path.TextChanged+=(s,e)=>{var backend=Engine.Backend(path.Text);status.Text=backend=="Mono"?"已识别 Mono 本体（适配验证版），可检查版本后安装。":backend=="IL2CPP"?"已识别 IL2CPP 本体，可检查适配版本。":"";};FormClosing+=(s,e)=>{if(busy)e.Cancel=true;};}
  async Task Export(){try{string root=path.Text;if(!File.Exists(Path.Combine(root,"MDPro3.exe")))throw new IOException("请选择包含 MDPro3.exe 的本体文件夹。");using(var dialog=new SaveFileDialog{Title="导出本体适配资料",Filter="ZIP 资料包|*.zip",FileName="MDPro3-适配资料-"+Engine.Backend(root)+".zip",InitialDirectory=Path.GetDirectoryName(Assembly.GetExecutingAssembly().Location)}){if(dialog.ShowDialog(this)!=DialogResult.OK)return;string output=dialog.FileName;busy=true;path.Enabled=browse.Enabled=install.Enabled=remove.Enabled=check.Enabled=export.Enabled=false;bar.Value=0;status.Text="正在整理版本资料…";try{await Task.Run(()=>engine.ExportInfo(root,output,(value,text)=>BeginInvoke(new Action(()=>{bar.Value=value;status.Text=text;}))));MessageBox.Show(this,"资料已导出，请将这个 ZIP 文件提供给开发者：\r\n"+output+"\r\n\r\n资料包含版本信息和 Managed 程序组件，不含卡组、存档、录像和账号配置。","适配资料已导出",MessageBoxButtons.OK,MessageBoxIcon.Information);}finally{busy=false;path.Enabled=browse.Enabled=install.Enabled=remove.Enabled=check.Enabled=export.Enabled=true;}}}catch(Exception ex){MessageBox.Show(this,ex.Message,"导出未完成",MessageBoxButtons.OK,MessageBoxIcon.Information);}}

  async Task Run(bool uninstall){string root=path.Text;busy=true;path.Enabled=browse.Enabled=install.Enabled=remove.Enabled=check.Enabled=export.Enabled=false;bar.Value=0;status.Text="正在检查目录…";try{await Task.Run(()=>{Action<int,string> update=(value,text)=>BeginInvoke(new Action(()=>{bar.Value=value;status.Text=text;}));if(uninstall)engine.Uninstall(root,update);else engine.Install(root,update);});MessageBox.Show(this,uninstall?"编辑器已卸载。":"安装完成。启动 MDPro3，在主菜单选择“决构编辑对局”。","决构编辑器",MessageBoxButtons.OK,MessageBoxIcon.Information);}catch(Exception ex){status.Text="操作未完成，已保留原有文件。";MessageBox.Show(this,ex.Message,"操作未完成",MessageBoxButtons.OK,MessageBoxIcon.Information);}finally{busy=false;path.Enabled=browse.Enabled=install.Enabled=remove.Enabled=check.Enabled=export.Enabled=true;}}
 }
 static class Program {
  [STAThread]static int Main(string[] args){try{if(args.Length>=2){var engine=new Engine();string mode=args[0],root=args[1];if(mode=="--export-info"){if(args.Length<3)throw new ArgumentException("需要 ZIP 保存路径");engine.ExportInfo(root,args[2],null);return 0;}if(mode=="--diagnose"){if(args.Length<3)throw new ArgumentException("需要资料保存路径");File.WriteAllText(args[2],engine.Describe(root),Encoding.UTF8);return 0;}if(mode=="--check")engine.Validate(root,true);else if(mode=="--install")engine.Install(root,null);else if(mode=="--uninstall")engine.Uninstall(root,null);else throw new ArgumentException("未知操作");if(args.Length>=3)File.WriteAllText(args[2],"SUCCESS "+mode,Encoding.UTF8);return 0;}Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);Application.Run(new SetupForm());return 0;}catch(Exception ex){if(args.Length>=3&&args[0]!="--export-info")File.WriteAllText(args[2],"FAILED "+ex.Message,Encoding.UTF8);else if(args.Length==0)MessageBox.Show(ex.Message,"决构编辑器安装器");return 1;}}
 }
